#!/usr/bin/env node
// Generates src/api/gen/v1.ts from src/api/openapi-v1.json (chapter 44,
// "API client and routes": types from the data API's OpenAPI document with
// openapi-typescript). The JSON is written by sprig-studio's test
// `studio_openapi_document_is_current` (SPRIG_STUDIO_REGEN=1), which fails
// when it drifts from the route table and the protos. `--check` fails when
// the generated file is stale.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = join(root, 'src/api/openapi-v1.json');
const out = join(root, 'src/api/gen/v1.ts');
const doc = JSON.parse(readFileSync(src, 'utf8'));
const ast = await openapiTS(doc);
const text =
  '// Generated by scripts/gen-api.mjs from src/api/openapi-v1.json. Do not edit.\n' + astToString(ast);
if (process.argv.includes('--check')) {
  let have = '';
  try {
    have = readFileSync(out, 'utf8');
  } catch {
    // missing
  }
  if (have !== text) {
    console.error('src/api/gen/v1.ts is stale: run pnpm gen:api');
    process.exit(1);
  }
  console.log('generated API types are current');
} else {
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, text);
  console.log(`wrote ${out}`);
}
